<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/deposits"
);

const headers = {
    "Authorization": "Bearer {VOTRE_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
    "X-Agency-Id": "1",
};

let body = {
    "client_uuid": "6ff8f7f6-1eb3-3525-be4a-3932c805afed",
    "client_id": "architecto",
    "discount": 39,
    "discount_percent": 7,
    "promo_code": "architecto",
    "promo_special_code": "architecto",
    "points_to_redeem": 39,
    "with_collection": true,
    "with_delivery": false,
    "collection_fee": 77,
    "delivery_fee": 8,
    "delivery_address": "y",
    "advanced": 60,
    "payment_method": "cash",
    "deposit_date": "2026-10-22T12:15:30",
    "retrieve_date": "2026-10-22T12:15:30",
    "notes": "architecto",
    "lines": [
        {
            "article_id": "architecto",
            "quantity": 22,
            "type_action": 0,
            "pricing_type": "kilo",
            "weight_kg": 77,
            "unit_price": 8,
            "designation": "architecto",
            "state": "architecto",
            "render_id": 16,
            "express": false,
            "color": "g",
            "defects": [
                "architecto"
            ],
            "internal_notes": "n"
        }
    ],
    "terminal": "b",
    "local_ref": "n",
    "discount_reason": "g"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

